'use strict';
const exportFormatNames={mp4:'MP4 · H.264 / AAC',webm:window.studioDesktop?.beginFrameExport?'WebM · VP9 / Opus':'WebM · VP8 / Opus',mov:'MOV · H.264 / AAC',gif:'GIF · silent loop'};
for(const [id,name]of Object.entries(exportFormatNames)){let option=$('videoFormat').querySelector('[value="'+id+'"]');if(!option){option=document.createElement('option');option.value=id;$('videoFormat').append(option)}option.textContent=name;if(['mov','gif'].includes(id)&&!window.studioDesktop?.beginFrameExport)option.disabled=true}
$('videoFormat').prepend($('videoFormat').querySelector('[value="mp4"]'));if(window.studioDesktop?.beginFrameExport)$('videoFormat').value='mp4';else $('videoFormat').value='webm';
$('exportDialog').querySelector('.note').id='exportFormatNote';$('videoFormat').closest('label').after(Object.assign(document.createElement('section'),{className:'export-range-settings',innerHTML:'<label>Export<select id="exportScope"><option value="project">Whole project</option><option value="scene">Current scene</option><option value="range">Time range</option></select></label><div id="exportRangeFields" class="rig-tools" hidden><label>Start (s)<input id="exportRangeStart" type="number" min="0" step="0.033333" value="0"></label><label>End (s)<input id="exportRangeEnd" type="number" min="0.033333" step="0.033333" value="1"></label></div><p id="exportOutputSummary" class="analysis-summary"></p>'}));
function readExportRange(){const scope=$('exportScope').value,total=totalDuration(),range=scope==='scene'?{start:sceneOffset(),end:sceneOffset()+current().duration}:scope==='range'?{start:+$('exportRangeStart').value,end:+$('exportRangeEnd').value}:{start:0,end:total};if(!Number.isFinite(range.start)||!Number.isFinite(range.end)||range.start<0||range.end>total+.001||range.end-range.start<1/30)throw Error('Choose at least one frame inside the project for export.');return range}
function updateExportSummary(){try{const geometry=exportGeometry($('resolution').value),range=readExportRange(),format=$('videoFormat').value;$('exportRangeFields').hidden=$('exportScope').value!=='range';$('exportOutputSummary').textContent=geometry.width+' × '+geometry.height+' · '+(Math.max(geometry.width,geometry.height)===3840&&Math.min(geometry.width,geometry.height)===2160?'4K':Math.max(geometry.width,geometry.height)===1920&&Math.min(geometry.width,geometry.height)===1080?'Full HD':geometry.width===geometry.height&&geometry.width>=1080?'Square high resolution':'draft')+' · '+(range.end-range.start).toFixed(2)+'s · 30 fps · .'+format;$('exportFormatNote').textContent=format==='gif'?'GIF is a silent 256-colour loop, limited to 20 seconds. MP4 keeps full video colour and audio.':window.studioDesktop?.beginFrameExport?'Every timeline frame renders at the selected dimensions before encoding. MP4 is the main video format; narration, music and effects are mixed into the export.':'Browser export records in real time. Keep this tab visible. MOV and GIF encoding are available in the updated desktop app.'}catch(e){$('exportOutputSummary').textContent=e.message}}
const openExportBeforeSettings=$('export').onclick;$('export').onclick=(...args)=>{if(!exportQueueRunning){$('exportScope').value='project';$('exportRangeStart').value=+globalTime().toFixed(3);$('exportRangeEnd').value=+totalDuration().toFixed(3)}const out=openExportBeforeSettings?.(...args);updateExportSummary();return out};
for(const id of ['exportScope','exportRangeStart','exportRangeEnd','videoFormat','resolution'])$(id).addEventListener('change',updateExportSummary);updateExportSummary();
